// src/components/Dashboard/Director/Estudiante/DirecEstudContentPanel.jsx

import React from 'react';

const DirecEstudContentPanel = () => {
  return (
    <div>
      <h3 className="text-xl font-bold">Formulario de Registro de Estudiante</h3>
      <p className="text-gray-600 mt-2">Aquí va el formulario para registrar un nuevo estudiante.</p>
    </div>
  );
};

export default DirecEstudContentPanel;
